previewCss:
.darma-loader-darma-b16-origami-crane-flap { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #fecdd3); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .72); position: relative; }
.darma-loader-darma-b16-origami-crane-flap .darma-loader-darma-b16-origami-crane-flap__bird { position: absolute; inset: 0; animation: darma-loader-darma-b16-origami-crane-flap-crane-glide calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b16-origami-crane-flap .darma-loader-darma-b16-origami-crane-flap__body { position: absolute; left: 30%; top: 38%; width: 44%; height: 34%; background: linear-gradient(var(--accent-2), var(--accent)); clip-path: polygon(0 20%, 62% 0, 100% 46%, 46% 100%); }
.darma-loader-darma-b16-origami-crane-flap .darma-loader-darma-b16-origami-crane-flap__wing { position: absolute; top: 12%; width: 38%; height: 44%; background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); }
.darma-loader-darma-b16-origami-crane-flap .darma-loader-darma-b16-origami-crane-flap__wing:nth-of-type(1) { left: 8%; clip-path: polygon(0 8%, 100% 52%, 62% 100%); transform-origin: 100% 60%; animation: darma-loader-darma-b16-origami-crane-flap-crane-left calc(var(--loader-speed, 1s) * .95) ease-in-out infinite; }
.darma-loader-darma-b16-origami-crane-flap .darma-loader-darma-b16-origami-crane-flap__wing:nth-of-type(2) { right: 8%; clip-path: polygon(100% 8%, 0 52%, 38% 100%); transform-origin: 0 60%; animation: darma-loader-darma-b16-origami-crane-flap-crane-right calc(var(--loader-speed, 1s) * .95) ease-in-out infinite; }
@keyframes darma-loader-darma-b16-origami-crane-flap-crane-left { 0%, 100% { transform: rotate(-26deg) scaleY(1); } 50% { transform: rotate(22deg) scaleY(.72); } }
@keyframes darma-loader-darma-b16-origami-crane-flap-crane-right { 0%, 100% { transform: rotate(26deg) scaleY(1); } 50% { transform: rotate(-22deg) scaleY(.72); } }
@keyframes darma-loader-darma-b16-origami-crane-flap-crane-glide { 0%, 100% { transform: translateY(4%); } 50% { transform: translateY(-6%); } }

